package com.nevereatsoggyweetbix;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.util.Arrays;
import net.runelite.api.AABB;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;

/** Removes selected actor silhouettes from the compass buffer. */
final class ActorCompassMask
{
	private int[] vertexX = new int[0];
	private int[] vertexY = new int[0];
	private final int[] triangleX = new int[3];
	private final int[] triangleY = new int[3];
	private final Rectangle2D.Double projectedBounds = new Rectangle2D.Double();
	private final Point2D.Double projectedPoint = new Point2D.Double();

	void erase(Graphics2D graphics, Client client, Actor actor, Model model, Rectangle bounds, CompassProjection projection)
	{
		if (model == null || model.getVerticesCount() == 0)
		{
			return;
		}
		LocalPoint location = actor.getLocalLocation();
		if (location == null || actor.getWorldView() == null || projection == null)
		{
			return;
		}
		Integer ground = CompassAnchor.groundHeight(client, actor.getWorldView(), location);
		if (ground == null)
		{
			return;
		}
		int height = ground - actor.getAnimationHeightOffset();
		AABB box = model.getAABB(actor.getCurrentOrientation());
		if (box != null)
		{
			Rectangle2D projected = ScreenBounds.projectBox(projection,
				location.getX() + box.getCenterX() - box.getExtremeX(),
				location.getX() + box.getCenterX() + box.getExtremeX(),
				location.getY() + box.getCenterZ() - box.getExtremeZ(),
				location.getY() + box.getCenterZ() + box.getExtremeZ(),
				height + box.getCenterY() - box.getExtremeY(), height + box.getCenterY() + box.getExtremeY(),
				projectedBounds, projectedPoint);
			if (projected != null && !projected.intersects(bounds))
			{
				return;
			}
		}
		int count = model.getVerticesCount();
		if (vertexX.length < count)
		{
			vertexX = new int[count];
			vertexY = new int[count];
		}
		Arrays.fill(vertexX, 0, count, Integer.MIN_VALUE);
		Arrays.fill(vertexY, 0, count, Integer.MIN_VALUE);
		Perspective.modelToCanvas(client, actor.getWorldView(), count,
			location.getX(), location.getY(), height, actor.getCurrentOrientation(),
			model.getVerticesX(), model.getVerticesZ(), model.getVerticesY(), vertexX, vertexY);
		eraseFaces(graphics, bounds, vertexX, vertexY, model.getFaceCount(),
			model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
			model.getFaceColors3(), model.getFaceTransparencies());
	}

	void eraseFaces(Graphics2D graphics, Rectangle bounds, int[] x, int[] y, int faceCount,
		int[] a, int[] b, int[] c, int[] colors3, byte[] transparencies)
	{
		Graphics2D mask = (Graphics2D) graphics.create();
		try
		{
			mask.setComposite(AlphaComposite.Clear);
			// Opaque triangle coverage prevents shared-edge seams in the mask.
			mask.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			for (int face = 0; face < faceCount; face++)
			{
				if ((colors3 != null && colors3[face] == -2)
					|| (transparencies != null && (transparencies[face] & 0xff) == 255))
				{
					continue;
				}
				int first = a[face], second = b[face], third = c[face];
				if (!valid(x, y, first) || !valid(x, y, second) || !valid(x, y, third))
				{
					continue;
				}
				// RuneLite draws negative screen-space winding; back faces cannot cover the compass.
				long area = ((long) x[second] - x[first]) * ((long) y[third] - y[first])
					- ((long) y[second] - y[first]) * ((long) x[third] - x[first]);
				if (area >= 0)
				{
					continue;
				}
				int minX = Math.min(x[first], Math.min(x[second], x[third]));
				int minY = Math.min(y[first], Math.min(y[second], y[third]));
				int maxX = Math.max(x[first], Math.max(x[second], x[third]));
				int maxY = Math.max(y[first], Math.max(y[second], y[third]));
				if (maxX < bounds.x || maxY < bounds.y || minX >= bounds.getMaxX() || minY >= bounds.getMaxY())
				{
					continue;
				}
				triangleX[0] = x[first]; triangleY[0] = y[first];
				triangleX[1] = x[second]; triangleY[1] = y[second];
				triangleX[2] = x[third]; triangleY[2] = y[third];
				mask.fillPolygon(triangleX, triangleY, 3);
			}
		}
		finally
		{
			mask.dispose();
		}
	}

	private static boolean valid(int[] x, int[] y, int index)
	{
		return index >= 0 && index < x.length && index < y.length
			&& x[index] != Integer.MIN_VALUE && y[index] != Integer.MIN_VALUE;
	}

	void clear()
	{
		vertexX = new int[0];
		vertexY = new int[0];
	}
}

package com.nevereatsoggyweetbix;

import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.function.Consumer;
import java.util.function.Function;

/** Event-maintained registry and bounded screen-overlap selection, independent of model loading. */
final class ActorMaskSelector<T>
{
	private static final class Entry<T>
	{
		private final int worldView;
		private final int index;
		private final T actor;
		private double overlap;

		private Entry(int worldView, int index, T actor)
		{
			this.worldView = worldView;
			this.index = index;
			this.actor = actor;
		}
	}

	private final Map<Long, Entry<T>> tracked = new HashMap<>();
	private final List<Entry<T>> candidates = new ArrayList<>();
	private final Comparator<Entry<T>> priority = Comparator
		.<Entry<T>>comparingDouble(entry -> entry.overlap).reversed()
		.thenComparingInt(entry -> entry.worldView).thenComparingInt(entry -> entry.index);
	private final PriorityQueue<Entry<T>> best = new PriorityQueue<>(priority.reversed());

	void spawn(int worldView, int index, T actor)
	{
		tracked.put(key(worldView, index), new Entry<>(worldView, index, actor));
		clearSelection();
	}

	void despawn(int worldView, int index, T actor)
	{
		long key = key(worldView, index);
		Entry<T> current = tracked.get(key);
		if (current != null && current.actor == actor)
		{
			tracked.remove(key);
		}
		clearSelection();
	}

	void removeWorld(int worldView)
	{
		tracked.values().removeIf(entry -> entry.worldView == worldView);
		clearSelection();
	}

	int select(boolean drawAbove, int limit, Rectangle2D drawingBounds, T excludedActor,
		Function<T, Rectangle2D> boundsLookup)
	{
		clearSelection();
		if (drawAbove || limit <= 0 || drawingBounds.isEmpty())
		{
			return 0;
		}
		for (Entry<T> entry : tracked.values())
		{
			if (entry.actor == excludedActor)
			{
				continue;
			}
			Rectangle2D actorBounds = boundsLookup.apply(entry.actor);
			double width = actorBounds == null ? drawingBounds.getWidth()
				: Math.min(drawingBounds.getMaxX(), actorBounds.getMaxX())
					- Math.max(drawingBounds.getMinX(), actorBounds.getMinX());
			double height = actorBounds == null ? drawingBounds.getHeight()
				: Math.min(drawingBounds.getMaxY(), actorBounds.getMaxY())
					- Math.max(drawingBounds.getMinY(), actorBounds.getMinY());
			if (width > 0 && height > 0)
			{
				entry.overlap = width * height;
				if (best.size() < limit)
				{
					best.offer(entry);
				}
				else if (priority.compare(entry, best.peek()) < 0)
				{
					best.poll();
					best.offer(entry);
				}
			}
		}
		// Drain worst-first, then reverse without copying the queue into a temporary array.
		while (!best.isEmpty())
		{
			candidates.add(best.poll());
		}
		Collections.reverse(candidates);
		return candidates.size();
	}

	void maskSelected(Consumer<T> maskActor)
	{
		try
		{
			for (Entry<T> entry : candidates)
			{
				// Each selected attempt consumes a slot, even when its model is unavailable.
				maskActor.accept(entry.actor);
			}
		}
		finally
		{
			clearSelection();
		}
	}

	void clearSelection()
	{
		candidates.clear();
		best.clear();
	}

	int size()
	{
		return tracked.size();
	}

	void clear()
	{
		tracked.clear();
		clearSelection();
	}

	private static long key(int worldView, int index)
	{
		return ((long) worldView << 32) | (index & 0xffffffffL);
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

abstract class ActorOcclusion<T extends Actor>
{
	protected final Client client;
	private final ActorMaskSelector<T> selector = new ActorMaskSelector<>();
	private final Map<Integer, CompassProjection> projections = new HashMap<>();
	private final Rectangle2D.Double projectedBounds = new Rectangle2D.Double();
	private final Point2D.Double projectedPoint = new Point2D.Double();
	private boolean active;

	ActorOcclusion(Client client)
	{
		this.client = client;
	}

	protected abstract Iterable<? extends T> actors(WorldView worldView);

	protected abstract int index(T actor);

	protected T excludedActor()
	{
		return null;
	}

	void start()
	{
		active = true;
		refresh();
	}

	void refresh()
	{
		reset();
		if (active)
		{
			seed(client.getTopLevelWorldView(), new HashSet<>());
		}
	}

	void worldLoaded(WorldView worldView)
	{
		if (active)
		{
			seed(worldView, new HashSet<>());
		}
	}

	private void seed(WorldView worldView, Set<Integer> visited)
	{
		if (worldView == null || !visited.add(worldView.getId()))
		{
			return;
		}
		for (T actor : actors(worldView))
		{
			spawn(actor);
		}
		for (WorldView child : worldView.worldViews())
		{
			seed(child, visited);
		}
	}

	void spawn(T actor)
	{
		if (active && actor != null && actor != excludedActor() && actor.getWorldView() != null)
		{
			selector.spawn(actor.getWorldView().getId(), index(actor), actor);
		}
	}

	void despawn(T actor)
	{
		if (actor != null && actor.getWorldView() != null)
		{
			selector.despawn(actor.getWorldView().getId(), index(actor), actor);
		}
	}

	void worldUnloaded(WorldView worldView)
	{
		removeWorld(worldView, new HashSet<>());
	}

	private void removeWorld(WorldView worldView, Set<Integer> visited)
	{
		if (worldView == null || !visited.add(worldView.getId()))
		{
			return;
		}
		selector.removeWorld(worldView.getId());
		projections.remove(worldView.getId());
		for (WorldView child : worldView.worldViews())
		{
			removeWorld(child, visited);
		}
	}

	int select(Rectangle bounds, boolean drawAbove, int limit)
	{
		discardSelection();
		if (!active || drawAbove || limit <= 0 || selector.size() == 0)
		{
			return 0;
		}
		return selector.select(false, limit, bounds, excludedActor(), this::coarseBounds);
	}

	void eraseSelected(Graphics2D graphics, Rectangle bounds, ActorCompassMask mask)
	{
		try
		{
			selector.maskSelected(actor ->
			{
				Model model = actor.getModel();
				if (model != null)
				{
					mask.erase(graphics, client, actor, model, bounds, projection(actor.getWorldView()));
				}
			});
		}
		finally
		{
			discardSelection();
		}
	}

	void discardSelection()
	{
		selector.clearSelection();
		projections.clear();
	}

	private Rectangle2D coarseBounds(T actor)
	{
		WorldView worldView = actor.getWorldView();
		LocalPoint location = actor.getLocalLocation();
		if (worldView == null || client.getWorldView(worldView.getId()) != worldView
			|| location == null || !worldView.contains(location))
		{
			projectedBounds.setRect(0, 0, 0, 0);
			return projectedBounds;
		}
		int footprint = actor.getFootprintSize();
		int height = Math.max(actor.getLogicalHeight(), actor.getModelHeight());
		Integer ground = CompassAnchor.groundHeight(client, worldView, location);
		if (footprint <= 0 || height <= 0 || ground == null)
		{
			return null;
		}
		// Cached actor fields only: requesting the animated model is reserved for selected slots.
		double radius = footprint * (double) Perspective.LOCAL_HALF_TILE_SIZE
			+ Perspective.LOCAL_TILE_SIZE;
		double base = ground - actor.getAnimationHeightOffset();
		return ScreenBounds.projectBox(projection(worldView), location.getX() - radius, location.getX() + radius,
			location.getY() - radius, location.getY() + radius,
			base - height - Perspective.LOCAL_TILE_SIZE, base + Perspective.LOCAL_HALF_TILE_SIZE,
			projectedBounds, projectedPoint);
	}

	private CompassProjection projection(WorldView worldView)
	{
		if (worldView == null)
		{
			return null;
		}
		int id = worldView.getId();
		if (!projections.containsKey(id))
		{
			projections.put(id, CompassProjection.create(client, worldView));
		}
		return projections.get(id);
	}

	void clear()
	{
		active = false;
		reset();
	}

	void reset()
	{
		selector.clear();
		projections.clear();
	}
}

package com.nevereatsoggyweetbix;

public enum AnchorMode
{
	PLAYER_FEET("Player feet"),
	PLAYER_HEAD("Player head"),
	PLAYER_TRUE_TILE("True tile"),
	SCREEN_CENTER("Screen center"),
	MOUSE_POSITION("Mouse"),
	MOUSE_TILE("Hovered tile");

	private final String label;

	AnchorMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Rectangle;
import java.awt.geom.Point2D;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

final class CompassAnchor
{
	final CompassProjection projection;
	final double x;
	final double y;
	final double height;
	final double translateX;
	final double translateY;

	CompassAnchor(CompassProjection projection, double x, double y, double height,
		double translateX, double translateY)
	{
		this.projection = projection;
		this.x = x;
		this.y = y;
		this.height = height;
		this.translateX = translateX;
		this.translateY = translateY;
	}

	static CompassAnchor resolve(Client client, Player player, Model model, NeverEatSoggyWeetbixConfig config,
		Rectangle viewport)
	{
		WorldView worldView = player.getWorldView();
		LocalPoint location = player.getLocalLocation();
		if (worldView == null || location == null)
		{
			return null;
		}
		AnchorMode mode = config.anchorMode();
		boolean mouseAnchor = mode == AnchorMode.MOUSE_POSITION || mode == AnchorMode.MOUSE_TILE;
		Point mouse = client.getMouseCanvasPosition();
		if (mouseAnchor)
		{
			if (mouse == null || !viewport.contains(mouse.getX(), mouse.getY()) || client.isMenuOpen())
			{
				return null;
			}
			if (mode == AnchorMode.MOUSE_TILE)
			{
				Tile tile = worldView.getSelectedSceneTile();
				if (tile == null && !worldView.isTopLevel())
				{
					worldView = client.getTopLevelWorldView();
					tile = worldView == null ? null : worldView.getSelectedSceneTile();
				}
				if (tile == null || tile.getPlane() != worldView.getPlane())
				{
					return null;
				}
				location = tile.getLocalLocation();
			}
		}
		else if (mode == AnchorMode.PLAYER_TRUE_TILE)
		{
			location = LocalPoint.fromWorld(worldView, player.getWorldLocation());
		}
		if (location == null || !worldView.contains(location))
		{
			return null;
		}
		CompassProjection projection = CompassProjection.create(client, worldView);
		if (projection == null)
		{
			return null;
		}
		double x = location.getX(), y = location.getY();
		Integer groundHeight = groundHeight(client, worldView, location);
		if (groundHeight == null)
		{
			return null;
		}
		double height = groundHeight;
		if (mode != AnchorMode.MOUSE_TILE && mode != AnchorMode.PLAYER_TRUE_TILE)
		{
			height -= player.getAnimationHeightOffset();
		}
		if (mode == AnchorMode.PLAYER_HEAD)
		{
			height -= modelTop(model, player.getLogicalHeight());
		}
		if (mode == AnchorMode.MOUSE_POSITION)
		{
			Point2D.Double ground = projection.unproject(mouse.getX(), mouse.getY(), height);
			if (ground == null)
			{
				return null;
			}
			x = ground.x;
			y = ground.y;
		}
		// RuneScape height coordinates increase downward: positive config offsets rise.
		height -= Math.max(-512, Math.min(512, config.heightOffset()));
		Point2D.Double center = projection.project(x, y, height);
		if (center == null)
		{
			return null;
		}
		double translateX = 0, translateY = 0;
		if (mode == AnchorMode.SCREEN_CENTER)
		{
			translateX = client.getCanvasWidth() / 2.0 - center.x;
			translateY = client.getCanvasHeight() / 2.0 - center.y;
		}
		return new CompassAnchor(projection, x, y, height, translateX, translateY);
	}

	Point2D.Double project(double dx, double dy)
	{
		Point2D.Double point = projection.project(x + dx, y + dy, height);
		if (point != null)
		{
			point.x += translateX;
			point.y += translateY;
		}
		return point;
	}

	static double modelTop(Model model, int fallback)
	{
		double top = 0;
		if (model != null)
		{
			float[] heights = model.getVerticesY();
			for (int i = 0; i < model.getVerticesCount(); i++)
			{
				top = Math.max(top, -heights[i]);
			}
		}
		return top > 0 ? top : Math.max(0, fallback);
	}

	static Integer groundHeight(Client client, WorldView worldView, LocalPoint location)
	{
		if (worldView.isTopLevel())
		{
			return Perspective.getTileHeight(client, location, worldView.getPlane());
		}
		WorldView top = client.getTopLevelWorldView();
		WorldEntity entity = top == null ? null : top.worldEntities().byIndex(worldView.getId());
		if (entity == null || entity.getLocalLocation() == null)
		{
			return null;
		}
		// Match Perspective.localToCanvas: subview height includes the entity's base elevation.
		LocalPoint base = entity.getLocalLocation();
		return worldView.getTileHeight(location.getX(), location.getY(), worldView.getPlane())
			+ top.getTileHeight(base.getX(), base.getY(), top.getPlane());
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Color;

enum CompassDirection
{
	N, NE, E, SE, S, SW, W, NW;

	static final CompassDirection[] ALL = values();
	final double x = Math.sin(ordinal() * Math.PI / 4);
	final double y = Math.cos(ordinal() * Math.PI / 4);

	boolean diagonal()
	{
		return (ordinal() & 1) != 0;
	}

	boolean lettersVisible(NeverEatSoggyWeetbixConfig config)
	{
		return diagonal() ? !config.hideDiagonals() : !config.hideCardinals();
	}

	boolean connectorVisible(NeverEatSoggyWeetbixConfig config, double heading)
	{
		if (!(diagonal() ? config.showDiagonalConnectors() : config.showCardinalConnectors()))
		{
			return false;
		}
		boolean onlyCurrent = config.onlyCurrentDirectionConnectors();
		boolean onlyOpposite = config.onlyOppositeDirectionConnectors();
		if (!onlyCurrent && !onlyOpposite)
		{
			return true;
		}
		int offset = Math.floorMod(ordinal() - current(heading, diagonal()), 8);
		return (onlyCurrent && offset == 0) || (onlyOpposite && offset == 4);
	}

	static int current(double heading, boolean diagonal)
	{
		double turns = heading / (Math.PI * 2);
		turns -= Math.floor(turns);
		int group = (int) Math.floor(turns * 4 + (diagonal ? 0 : 0.5));
		return (group * 2 + (diagonal ? 1 : 0)) & 7;
	}

	Color color(NeverEatSoggyWeetbixConfig config, double heading)
	{
		int role = Math.floorMod(ordinal() - current(heading, diagonal()), 8) / 2;
		if (diagonal())
		{
			switch (role)
			{
				case 0: return config.currentSubColor();
				case 1: return config.rightSubColor();
				case 2: return config.oppositeSubColor();
				default: return config.leftSubColor();
			}
		}
		switch (role)
		{
			case 0: return config.currentColor();
			case 1: return config.rightColor();
			case 2: return config.oppositeColor();
			default: return config.leftColor();
		}
	}

	static Color withOpacity(Color color, int percent)
	{
		int alpha = (int) Math.round(color.getAlpha() * Math.max(0, Math.min(100, percent)) / 100.0);
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Font;
import net.runelite.client.config.FontType;
import net.runelite.client.ui.FontManager;

final class CompassFonts
{
	static final int DEFAULT_MAIN_SIZE = 24;
	static final int DEFAULT_SUB_SIZE = 20;

	final Font cardinal;
	final Font diagonal;

	private CompassFonts(Font cardinal, Font diagonal)
	{
		this.cardinal = cardinal;
		this.diagonal = diagonal;
	}

	static CompassFonts fromConfig(NeverEatSoggyWeetbixConfig config)
	{
		if (!config.useCustomFont())
		{
			return new CompassFonts(
				FontManager.getRunescapeBoldFont().deriveFont((float) DEFAULT_MAIN_SIZE),
				FontManager.getRunescapeSmallFont().deriveFont((float) DEFAULT_SUB_SIZE));
		}
		return new CompassFonts(
			configuredFont(config.customFont(), DEFAULT_MAIN_SIZE),
			configuredFont(config.subDirectionFont(), DEFAULT_SUB_SIZE));
	}

	private static Font configuredFont(FontType selected, int defaultSize)
	{
		Font font = selected == null ? null : selected.getFont();
		if (font == null)
		{
			font = new Font(Font.SANS_SERIF, Font.PLAIN, defaultSize);
		}
		// Bound damaged/hand-edited settings before allocating glyph outlines.
		float size = Float.isFinite(font.getSize2D())
			? Math.max(1f, Math.min(512f, font.getSize2D())) : defaultSize;
		return font.deriveFont(size);
	}
}

package com.nevereatsoggyweetbix;

import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.util.Arrays;

final class CompassGeometry
{
	static final int SAMPLES = 256;
	private static final double[] CIRCLE_X = new double[SAMPLES + 1];
	private static final double[] CIRCLE_Y = new double[SAMPLES + 1];

	static
	{
		for (int i = 0; i <= SAMPLES; i++)
		{
			CIRCLE_X[i] = Math.sin((i % SAMPLES) * Math.PI * 2 / SAMPLES);
			CIRCLE_Y[i] = Math.cos((i % SAMPLES) * Math.PI * 2 / SAMPLES);
		}
	}

	final Path2D.Double inner = new Path2D.Double();
	final Path2D.Double outer = new Path2D.Double();
	final DirectionalIndicatorGeometry indicator = new DirectionalIndicatorGeometry();
	final DirectionalIndicatorGeometry oppositeIndicator = new DirectionalIndicatorGeometry();
	final Path2D.Double[] spokes = new Path2D.Double[8];
	final Point2D.Double[] labels = new Point2D.Double[8];
	final double[] rotations = new double[8];
	double outerRadius = Double.NaN;
	private final Point2D.Double[] labelRing = new Point2D.Double[SAMPLES];
	private final double[] labelLengths = new double[SAMPLES];
	private CompassAnchor labelAnchor;
	private double labelRadius;
	private boolean labelRingReady;

	CompassGeometry()
	{
		for (int i = 0; i < spokes.length; i++)
		{
			spokes[i] = new Path2D.Double();
		}
	}

	void update(CompassAnchor anchor, double radius, double bandWidth)
	{
		inner.reset();
		outer.reset();
		indicator.path.reset();
		oppositeIndicator.path.reset();
		outerRadius = Double.NaN;
		labelAnchor = null;
		labelRingReady = false;
		Arrays.fill(labels, null);
		Arrays.fill(rotations, 0);
		for (Path2D.Double spoke : spokes)
		{
			spoke.reset();
		}
		Point2D.Double center = anchor.project(0, 0);
		double pixelScale = anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
		double worldGap = bandWidth / pixelScale;
		if (center == null || !Double.isFinite(radius) || radius < 0
			|| !Double.isFinite(worldGap) || worldGap < 0)
		{
			return;
		}
		// One world-space radius for each ring: no per-point screen-space offsets.
		outerRadius = radius + worldGap;
		labelRadius = radius + worldGap / 2;
		labelAnchor = anchor;
		boolean innerPenDown = false;
		boolean outerPenDown = false;
		for (int i = 0; i <= SAMPLES; i++)
		{
			Point2D.Double point = anchor.project(CIRCLE_X[i] * radius, CIRCLE_Y[i] * radius);
			Point2D.Double outside = anchor.project(CIRCLE_X[i] * outerRadius, CIRCLE_Y[i] * outerRadius);
			if (radius > 0)
			{
				innerPenDown = append(inner, point, innerPenDown);
			}
			outerPenDown = append(outer, outside, outerPenDown);
		}
		for (CompassDirection direction : CompassDirection.ALL)
		{
			int index = direction.ordinal();
			Point2D.Double label = anchor.project(direction.x * labelRadius, direction.y * labelRadius);
			labels[index] = label;
			rotations[index] = label == null ? 0 : Math.atan2(label.y - center.y, label.x - center.x) + Math.PI / 2;
			Path2D.Double spoke = spokes[index];
			Point2D.Double start = anchor.project(direction.x * radius * 0.35, direction.y * radius * 0.35);
			Point2D.Double end = anchor.project(direction.x * radius * 0.85, direction.y * radius * 0.85);
			if (radius > 0 && start != null && end != null)
			{
				spoke.moveTo(start.x, start.y);
				spoke.lineTo(end.x, end.y);
			}
		}
	}

	void updateCurvedLabels(CompassAnchor anchor, double minimumRadius, double labelClearance, double bandWidth)
	{
		double scale = anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
		// Preserve the circle used to lay out the words; their length is not radial padding.
		double centerRadius = minimumRadius + labelClearance / (2 * scale);
		double gap = bandWidth / scale;
		for (int iteration = 0; iteration < 3; iteration++)
		{
			double normalScale = scale;
			for (int sample = 0; sample < SAMPLES; sample += 8)
			{
				double dx = CIRCLE_X[sample], dy = CIRCLE_Y[sample];
				Point2D.Double point = anchor.project(dx * centerRadius, dy * centerRadius);
				Point2D.Double radial = anchor.project(dx * (centerRadius + 1), dy * (centerRadius + 1));
				Point2D.Double tangent = anchor.project(dx * centerRadius + dy, dy * centerRadius - dx);
				if (point == null || radial == null || tangent == null)
				{
					continue;
				}
				double tx = tangent.x - point.x, ty = tangent.y - point.y;
				double normal = Math.abs((radial.x - point.x) * ty - (radial.y - point.y) * tx) / Math.hypot(tx, ty);
				if (Double.isFinite(normal) && normal > 1e-6)
				{
					normalScale = Math.min(normalScale, normal);
				}
			}
			// Text keeps its screen height, so account for the floor's foreshortening.
			gap = bandWidth / normalScale;
			double requiredCenter = minimumRadius + gap / 2;
			if (centerRadius >= requiredCenter)
			{
				break;
			}
			centerRadius = requiredCenter;
		}
		update(anchor, Math.max(minimumRadius, centerRadius - gap / 2), gap * scale);
	}

	boolean prepareLabelRing()
	{
		if (labelAnchor == null || !(labelRadius > 0))
		{
			return false;
		}
		if (!labelRingReady)
		{
			for (int i = 0; i < SAMPLES; i++)
			{
				labelRing[i] = labelAnchor.project(CIRCLE_X[i] * labelRadius, CIRCLE_Y[i] * labelRadius);
			}
			for (int i = 0; i < SAMPLES; i++)
			{
				Point2D.Double point = labelRing[i], next = labelRing[(i + 1) % SAMPLES];
				labelLengths[i] = point == null || next == null ? Double.NaN : point.distance(next);
			}
			labelRingReady = true;
		}
		return true;
	}

	/** Place a character by screen arc length, with its baseline tangent to the projected ring. */
	boolean labelTransform(CompassDirection direction, double offset, AffineTransform transform)
	{
		if (!labelRingReady || !Double.isFinite(offset))
		{
			return false;
		}
		int index = direction.ordinal() * SAMPLES / CompassDirection.ALL.length;
		int step = offset < 0 ? -1 : 1;
		double remaining = Math.abs(offset);
		for (int segment = 0; segment < SAMPLES; segment++)
		{
			int next = Math.floorMod(index + step, SAMPLES);
			int start = step > 0 ? index : next;
			double length = labelLengths[start];
			if (!Double.isFinite(length))
			{
				return false;
			}
			if (length > 1e-9 && remaining <= length)
			{
				Point2D.Double a = labelRing[start], b = labelRing[(start + 1) % SAMPLES];
				double fraction = step > 0 ? remaining / length : 1 - remaining / length;
				double dx = b.x - a.x, dy = b.y - a.y;
				Point2D.Double before = labelRing[Math.floorMod(start - 1, SAMPLES)];
				Point2D.Double after = labelRing[(start + 2) % SAMPLES];
				if (before != null && after != null)
				{
					// Interpolate tangents to avoid visible angle changes at sample boundaries.
					dx = (1 - fraction) * (b.x - before.x) + fraction * (after.x - a.x);
					dy = (1 - fraction) * (b.y - before.y) + fraction * (after.y - a.y);
				}
				transform.setToTranslation(a.x + (b.x - a.x) * fraction, a.y + (b.y - a.y) * fraction);
				transform.rotate(Math.atan2(dy, dx));
				return true;
			}
			remaining -= length;
			index = next;
		}
		return false;
	}

	void updateIndicators(CompassAnchor anchor, double heading, NeverEatSoggyWeetbixConfig config)
	{
		indicator.path.reset();
		oppositeIndicator.path.reset();
		double indicatorHeading = DirectionalIndicatorGeometry.rotationHeading(heading, config);
		if (config.directionalIndicatorEnabled())
		{
			indicator.update(anchor, outerRadius, indicatorHeading, config);
		}
		if (config.oppositeIndicator())
		{
			// Keep an exact opposite even with odd rotation step counts.
			oppositeIndicator.update(anchor, outerRadius, indicatorHeading + Math.PI, config);
		}
	}

	private static boolean append(Path2D.Double path, Point2D.Double point, boolean penDown)
	{
		if (point == null)
		{
			return false;
		}
		if (penDown)
		{
			path.lineTo(point.x, point.y);
		}
		else
		{
			path.moveTo(point.x, point.y);
		}
		return true;
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Shape;
import java.awt.font.GlyphVector;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;

/** Font outlines cached until the text or font changes; placement follows the current camera. */
final class CompassLabel
{
	final Rectangle2D bounds;
	private final Shape outline;
	private final Shape[] glyphs;
	private final double[] offsets;

	CompassLabel(GlyphVector vector)
	{
		outline = vector.getOutline();
		bounds = outline.getBounds2D();
		glyphs = new Shape[vector.getNumGlyphs()];
		offsets = new double[glyphs.length];
		for (int i = 0; i < glyphs.length; i++)
		{
			Rectangle2D glyphBounds = vector.getGlyphVisualBounds(i).getBounds2D();
			if (!glyphBounds.isEmpty())
			{
				offsets[i] = glyphBounds.getCenterX() - bounds.getCenterX();
				glyphs[i] = AffineTransform.getTranslateInstance(-glyphBounds.getCenterX(), -bounds.getCenterY())
					.createTransformedShape(vector.getGlyphOutline(i));
			}
		}
	}

	Shape straight(Point2D.Double position, double rotation)
	{
		AffineTransform transform = AffineTransform.getTranslateInstance(position.x, position.y);
		transform.rotate(rotation);
		transform.translate(-bounds.getCenterX(), -bounds.getCenterY());
		return transform.createTransformedShape(outline);
	}

	Shape curved(CompassGeometry geometry, CompassDirection direction)
	{
		Path2D.Double word = new Path2D.Double();
		AffineTransform transform = new AffineTransform();
		for (int i = 0; i < glyphs.length; i++)
		{
			if (glyphs[i] == null)
			{
				continue;
			}
			if (!geometry.labelTransform(direction, offsets[i], transform))
			{
				// Do not bridge a clipped section of the ring or wrap a word around a full turn.
				return null;
			}
			word.append(glyphs[i].getPathIterator(transform), false);
		}
		return word;
	}
}

package com.nevereatsoggyweetbix;

import java.awt.geom.Point2D;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Projection;
import net.runelite.api.WorldView;

/** Camera-space affine transform followed by RuneLite's perspective divide. */
final class CompassProjection
{
	private static final double NEAR_PLANE = 50;
	private final double[][] matrix;
	private final double centerX;
	private final double centerY;
	private final double scale;

	CompassProjection(double[][] matrix, double centerX, double centerY, double scale)
	{
		this.matrix = matrix;
		this.centerX = centerX;
		this.centerY = centerY;
		this.scale = scale;
	}

	static CompassProjection create(Client client, WorldView worldView)
	{
		if (client.getScale() <= 0)
		{
			return null;
		}
		double[][] matrix;
		if (worldView.isTopLevel())
		{
			boolean gpu = client.isGpu();
			double yaw = gpu ? client.getCameraFpYaw() : client.getCameraYaw() * Perspective.UNIT14;
			double pitch = gpu ? client.getCameraFpPitch() : client.getCameraPitch() * Perspective.UNIT14;
			matrix = cameraMatrix(yaw, pitch,
				gpu ? client.getCameraFpX() : client.getCameraX(),
				gpu ? client.getCameraFpY() : client.getCameraY(),
				gpu ? client.getCameraFpZ() : client.getCameraZ());
		}
		else
		{
			Projection projection = worldView.getCanvasProjection();
			if (projection == null)
			{
				return null;
			}
			// Sample the affine transform in local X, local Y, then world height.
			// A tile-sized basis avoids losing precision to float translations.
			float[] origin = projection.project(0, 0, 0);
			float[][] basis = {
				projection.project(Perspective.LOCAL_TILE_SIZE, 0, 0),
				projection.project(0, 0, Perspective.LOCAL_TILE_SIZE),
				projection.project(0, Perspective.LOCAL_TILE_SIZE, 0)
			};
			matrix = new double[3][4];
			for (int row = 0; row < 3; row++)
			{
				for (int col = 0; col < 3; col++)
				{
					matrix[row][col] = (basis[col][row] - origin[row]) / Perspective.LOCAL_TILE_SIZE;
				}
				matrix[row][3] = origin[row];
			}
		}
		return new CompassProjection(matrix,
			client.getViewportXOffset() + client.getViewportWidth() / 2.0,
			client.getViewportYOffset() + client.getViewportHeight() / 2.0, client.getScale());
	}

	static double[][] cameraMatrix(double yaw, double pitch, double x, double y, double z)
	{
		double sy = Math.sin(yaw), cy = Math.cos(yaw);
		double sp = Math.sin(pitch), cp = Math.cos(pitch);
		double[][] m = {
			{cy, sy, 0, 0},
			{sy * sp, -cy * sp, cp, 0},
			{-sy * cp, cy * cp, sp, 0}
		};
		for (double[] row : m)
		{
			row[3] = -row[0] * x - row[1] * y - row[2] * z;
		}
		return m;
	}

	Point2D.Double project(double x, double y, double height)
	{
		Point2D.Double result = new Point2D.Double();
		return project(x, y, height, result) ? result : null;
	}

	boolean project(double x, double y, double height, Point2D.Double result)
	{
		double depth = transform(2, x, y, height);
		if (!Double.isFinite(depth) || depth < NEAR_PLANE)
		{
			return false;
		}
		double screenX = centerX + transform(0, x, y, height) * scale / depth;
		double screenY = centerY + transform(1, x, y, height) * scale / depth;
		if (!Double.isFinite(screenX) || !Double.isFinite(screenY))
		{
			return false;
		}
		result.setLocation(screenX, screenY);
		return true;
	}

	/** Intersect a screen ray with the horizontal plane at the supplied height. */
	Point2D.Double unproject(double screenX, double screenY, double height)
	{
		if (!(scale > 0))
		{
			return null;
		}
		double u = (screenX - centerX) / scale;
		double v = (screenY - centerY) / scale;
		double a = matrix[0][0] - u * matrix[2][0];
		double b = matrix[0][1] - u * matrix[2][1];
		double c = matrix[1][0] - v * matrix[2][0];
		double d = matrix[1][1] - v * matrix[2][1];
		double e = -(matrix[0][2] - u * matrix[2][2]) * height - matrix[0][3] + u * matrix[2][3];
		double f = -(matrix[1][2] - v * matrix[2][2]) * height - matrix[1][3] + v * matrix[2][3];
		double determinant = a * d - b * c;
		if (!Double.isFinite(determinant) || Math.abs(determinant) < 1e-9)
		{
			return null;
		}
		double x = (e * d - b * f) / determinant;
		double y = (a * f - e * c) / determinant;
		return project(x, y, height) == null ? null : new Point2D.Double(x, y);
	}

	double heading()
	{
		// Camera-right is independent of pitch, including a near-vertical camera.
		return Math.atan2(-matrix[0][1], matrix[0][0]);
	}

	/** Pixel scale along camera-right on the horizontal plane, measured at the anchor. */
	double horizontalScaleAt(double x, double y, double height)
	{
		double depth = transform(2, x, y, height);
		double horizontalScale = scale * Math.hypot(matrix[0][0], matrix[0][1]) / depth;
		return depth >= NEAR_PLANE && Double.isFinite(horizontalScale) && horizontalScale > 0
			? horizontalScale : Double.NaN;
	}

	private double transform(int row, double x, double y, double z)
	{
		return matrix[row][0] * x + matrix[row][1] * y + matrix[row][2] * z + matrix[row][3];
	}
}

package com.nevereatsoggyweetbix;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;

/** Isolated text RGBA layer: foreground coverage replaces shadows rather than blending with them. */
final class CompassTextLayer
{
	private BufferedImage layer;
	private BufferedImage coverage;

	void draw(Graphics2D target, Shape[] glyphs, Color[] colors, Color shadow, int offset)
	{
		Rectangle bounds = bounds(glyphs, offset, target.getClipBounds());
		if (bounds.isEmpty())
		{
			return;
		}
		ensureBuffers(bounds.width, bounds.height);
		int stride = layer.getWidth();
		int[] pixels = ((DataBufferInt) layer.getRaster().getDataBuffer()).getData();
		int[] mask = ((DataBufferInt) coverage.getRaster().getDataBuffer()).getData();
		for (int y = 0; y < bounds.height; y++)
		{
			Arrays.fill(pixels, y * stride, y * stride + bounds.width, 0);
		}
		Graphics2D shadows = layer.createGraphics();
		Graphics2D foreground = coverage.createGraphics();
		try
		{
			shadows.setRenderingHints(target.getRenderingHints());
			shadows.translate(-bounds.x, -bounds.y);
			shadows.clip(bounds);
			shadows.setColor(shadow);
			AffineTransform shift = AffineTransform.getTranslateInstance(offset, offset);
			for (Shape glyph : glyphs)
			{
				if (glyph != null)
				{
					shadows.fill(shift.createTransformedShape(glyph));
				}
			}
			foreground.setRenderingHints(target.getRenderingHints());
			foreground.translate(-bounds.x, -bounds.y);
			foreground.clip(bounds);
			foreground.setColor(Color.WHITE);
			foreground.setComposite(AlphaComposite.Src);
			for (int i = 0; i < glyphs.length; i++)
			{
				Shape glyph = glyphs[i];
				if (glyph == null)
				{
					continue;
				}
				Rectangle patch = glyph.getBounds();
				patch.grow(1, 1);
				patch = patch.intersection(bounds);
				if (patch.isEmpty())
				{
					continue;
				}
				int startX = patch.x - bounds.x, startY = patch.y - bounds.y;
				for (int y = startY; y < startY + patch.height; y++)
				{
					Arrays.fill(mask, y * stride + startX, y * stride + startX + patch.width, 0);
				}
				foreground.fill(glyph);
				Color color = colors[i];
				for (int y = startY; y < startY + patch.height; y++)
				{
					for (int x = startX; x < startX + patch.width; x++)
					{
						int index = y * stride + x;
						int amount = mask[index] >>> 24;
						if (amount != 0)
						{
							int alpha = (color.getAlpha() * amount + 127) / 255;
							pixels[index] = (alpha << 24) | (color.getRGB() & 0xffffff);
						}
					}
				}
			}
		}
		finally
		{
			shadows.dispose();
			foreground.dispose();
		}
		// Src is confined to our coverage buffer; the finished text blends normally with the scene.
		target.drawImage(layer, bounds.x, bounds.y, bounds.x + bounds.width, bounds.y + bounds.height,
			0, 0, bounds.width, bounds.height, null);
	}

	static Rectangle bounds(Shape[] glyphs, int offset, Rectangle clip)
	{
		Rectangle2D result = null;
		for (Shape glyph : glyphs)
		{
			if (glyph != null)
			{
				Rectangle2D box = glyph.getBounds2D();
				Rectangle2D combined = box.createUnion(new Rectangle2D.Double(
					box.getX() + offset, box.getY() + offset, box.getWidth(), box.getHeight()));
				result = result == null ? combined : result.createUnion(combined);
			}
		}
		if (result == null)
		{
			return new Rectangle();
		}
		double minX = Math.floor(result.getMinX() - 1), minY = Math.floor(result.getMinY() - 1);
		double maxX = Math.ceil(result.getMaxX() + 1), maxY = Math.ceil(result.getMaxY() + 1);
		if (clip != null)
		{
			minX = Math.max(minX, clip.getMinX()); minY = Math.max(minY, clip.getMinY());
			maxX = Math.min(maxX, clip.getMaxX()); maxY = Math.min(maxY, clip.getMaxY());
		}
		return maxX > minX && maxY > minY
			? new Rectangle((int) minX, (int) minY, (int) (maxX - minX), (int) (maxY - minY)) : new Rectangle();
	}

	private void ensureBuffers(int width, int height)
	{
		if (layer == null || layer.getWidth() < width || layer.getHeight() < height)
		{
			int nextWidth = layer == null ? width : Math.max(width, layer.getWidth());
			int nextHeight = layer == null ? height : Math.max(height, layer.getHeight());
			clear();
			layer = new BufferedImage(nextWidth, nextHeight, BufferedImage.TYPE_INT_ARGB);
			coverage = new BufferedImage(nextWidth, nextHeight, BufferedImage.TYPE_INT_ARGB);
		}
	}

	void clear()
	{
		if (layer != null)
		{
			layer.flush(); coverage.flush();
			layer = null; coverage = null;
		}
	}
}

package com.nevereatsoggyweetbix;

public enum DirectionLabelMode
{
	ABBREVIATIONS("Short"),
	FULL_NAMES("Full"),
	CUSTOM("Custom");

	private final String label;

	DirectionLabelMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.nevereatsoggyweetbix;

import java.util.Locale;

final class DirectionLabels
{
	private static final String[] FULL_NAMES = {
		"North", "Northeast", "East", "Southeast", "South", "Southwest", "West", "Northwest"
	};

	private DirectionLabels()
	{
	}

	static String[] resolve(NeverEatSoggyWeetbixConfig config)
	{
		if (config.labelMode() == DirectionLabelMode.FULL_NAMES)
		{
			return FULL_NAMES.clone();
		}
		String[] labels = new String[CompassDirection.ALL.length];
		for (CompassDirection direction : CompassDirection.ALL)
		{
			labels[direction.ordinal()] = direction.name();
		}
		String definitions = config.customLabels();
		if (config.labelMode() != DirectionLabelMode.CUSTOM || definitions == null)
		{
			return labels;
		}
		for (String line : definitions.split("\\R"))
		{
			int separator = line.indexOf('=');
			if (separator < 0)
			{
				continue;
			}
			String key = line.substring(0, separator).trim().toUpperCase(Locale.ROOT);
			for (CompassDirection direction : CompassDirection.ALL)
			{
				if (direction.name().equals(key))
				{
					labels[direction.ordinal()] = line.substring(separator + 1).trim();
					break;
				}
			}
		}
		return labels;
	}
}

package com.nevereatsoggyweetbix;

import java.awt.geom.Path2D;
import java.awt.geom.Point2D;

/** A reusable closed silhouette projected from the compass's horizontal plane. */
final class DirectionalIndicatorGeometry
{
	private static final double[][] TRIANGLE = {{-0.5, 0}, {0.5, 0}, {0, 1}};
	private static final double[][] ARROW = {
		{-0.18, 0}, {0.18, 0}, {0.18, 0.5}, {0.5, 0.5},
		{0, 1}, {-0.5, 0.5}, {-0.18, 0.5}
	};
	private static final double[][] SQUARE = {{-0.5, 0}, {0.5, 0}, {0.5, 1}, {-0.5, 1}};
	private static final double[][] CIRCLE = new double[64][2];

	static
	{
		for (int i = 0; i < CIRCLE.length; i++)
		{
			double angle = i * Math.PI * 2 / CIRCLE.length;
			CIRCLE[i][0] = Math.sin(angle) / 2;
			CIRCLE[i][1] = (1 - Math.cos(angle)) / 2;
		}
	}

	final Path2D.Double path = new Path2D.Double();

	static double rotationHeading(double heading, NeverEatSoggyWeetbixConfig config)
	{
		if (!config.limitRotationSteps() || !Double.isFinite(heading))
		{
			return heading;
		}
		int steps = Math.max(1, Math.min(360, config.rotationSteps()));
		double turn = Math.PI * 2;
		double step = turn / steps;
		// Round signed angles first: adding a turn before rounding can lose negative halfway ties.
		double rounded = Math.floor((heading % turn) / step + 0.5);
		return ((rounded % steps + steps) % steps) * step;
	}

	void update(CompassAnchor anchor, double outerRadius, double heading, NeverEatSoggyWeetbixConfig config)
	{
		path.reset();
		if (!Double.isFinite(outerRadius) || outerRadius < 0
			|| !Double.isFinite(heading))
		{
			return;
		}
		double scale = anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
		double dx = Math.sin(heading), dy = Math.cos(heading);
		Point2D.Double edge = anchor.project(dx * outerRadius, dy * outerRadius);
		Point2D.Double radial = anchor.project(dx * (outerRadius + 1), dy * (outerRadius + 1));
		Point2D.Double tangent = anchor.project(dx * outerRadius + dy, dy * outerRadius - dx);
		if (!(scale > 0) || !Double.isFinite(scale) || edge == null || radial == null || tangent == null)
		{
			return;
		}
		// Stroke widths are screen pixels. Use the projected normal scale for their clearance,
		// so a low camera pitch does not collapse the stroke clearance with the ground gap.
		double tx = tangent.x - edge.x, ty = tangent.y - edge.y;
		double normalScale = Math.abs((radial.x - edge.x) * ty - (radial.y - edge.y) * tx) / Math.hypot(tx, ty);
		if (!Double.isFinite(normalScale) || normalScale < 1e-6)
		{
			return;
		}
		double strokeClearance = (thickness(config.directionalIndicatorLineThickness())
			+ (config.showOuterRing() ? thickness(config.outerThickness()) : 0)) / 2.0;
		double margin = Math.max(0, Math.min(128, config.directionalIndicatorMargin()));
		double start = outerRadius + margin / scale + strokeClearance / normalScale;
		double width = Math.max(1, Math.min(128, config.directionalIndicatorWidth())) / scale;
		double height = Math.max(1, Math.min(128, config.directionalIndicatorHeight())) / scale;
		double[][] vertices;
		switch (config.directionalIndicatorShape())
		{
			case ARROW: vertices = ARROW; break;
			case SQUARE: vertices = SQUARE; break;
			case CIRCLE: vertices = CIRCLE; break;
			default: vertices = TRIANGLE; break;
		}
		for (int i = 0; i < vertices.length; i++)
		{
			double across = vertices[i][0] * width;
			double outward = start + vertices[i][1] * height;
			Point2D.Double point = anchor.project(dx * outward + dy * across, dy * outward - dx * across);
			if (point == null)
			{
				path.reset();
				return;
			}
			if (i == 0)
			{
				path.moveTo(point.x, point.y);
			}
			else
			{
				path.lineTo(point.x, point.y);
			}
		}
		path.closePath();
	}

	private static int thickness(int value)
	{
		return Math.max(1, Math.min(12, value));
	}
}

