package com.nevereatsoggyweetbix;

import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;

final class ScreenBounds
{
	private ScreenBounds()
	{
	}

	/** Null means uncertain/near-plane crossing; an empty box is definitely invisible. */
	static Rectangle2D projectBox(CompassProjection projection, double minX, double maxX,
		double minY, double maxY, double minHeight, double maxHeight)
	{
		return projectBox(projection, minX, maxX, minY, maxY, minHeight, maxHeight,
			new Rectangle2D.Double(), new Point2D.Double());
	}

	/** The returned box aliases result; consume it before reusing the scratch objects. */
	static Rectangle2D projectBox(CompassProjection projection, double minX, double maxX,
		double minY, double maxY, double minHeight, double maxHeight,
		Rectangle2D.Double result, Point2D.Double point)
	{
		if (projection == null)
		{
			return null;
		}
		result.setRect(0, 0, 0, 0);
		int visible = 0;
		for (int corner = 0; corner < 8; corner++)
		{
			if (projection.project((corner & 1) == 0 ? minX : maxX,
				(corner & 2) == 0 ? minY : maxY, (corner & 4) == 0 ? minHeight : maxHeight, point))
			{
				visible++;
				if (visible == 1)
				{
					result.setRect(point.x, point.y, 0, 0);
				}
				else
				{
					result.add(point);
				}
			}
		}
		return visible == 0 || visible == 8 ? result : null;
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class ActorCompassMaskTest
{
	private static BufferedImage filledImage()
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB_PRE);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(255, 0, 0, 128));
		graphics.fillRect(0, 0, 40, 40);
		graphics.dispose();
		return image;
	}

	@Test
	public void projectedFacesRemoveCoverageButPreserveGapsInSilhouette()
	{
		BufferedImage image = filledImage();
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(new Color(255, 0, 0, 128));
			new ActorCompassMask().eraseFaces(graphics, new Rectangle(0, 0, 40, 40),
				new int[]{2, 14, 2, 24, 36, 36}, new int[]{2, 2, 36, 2, 2, 36},
				2, new int[]{0, 3}, new int[]{2, 5}, new int[]{1, 4}, null, null);
			assertEquals(0, image.getRGB(4, 8) >>> 24);
			assertEquals(0, image.getRGB(34, 8) >>> 24);
			assertEquals(128, image.getRGB(20, 8) >>> 24);
			assertEquals(128, image.getRGB(20, 38) >>> 24);
			// Masking must not leak its composite or color back into later overlays.
			graphics.fillRect(20, 20, 1, 1);
			assertEquals(192, image.getRGB(20, 20) >>> 24);
			// Large projected faces must retain their winding when the signed area exceeds an int.
			new ActorCompassMask().eraseFaces(graphics, new Rectangle(0, 0, 40, 40),
				new int[]{-50000, 50000, 0}, new int[]{50000, 50000, -150000},
				1, new int[]{0}, new int[]{1}, new int[]{2}, null, null);
			assertEquals(0, image.getRGB(20, 38) >>> 24);
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void transparentHiddenInvalidOffscreenAndBackFacesDoNotMask()
	{
		for (int variant = 0; variant < 6; variant++)
		{
			BufferedImage image = filledImage();
			Graphics2D graphics = image.createGraphics();
			try
			{
				int[] x = {2, 36, variant == 2 ? Integer.MIN_VALUE : 2};
				new ActorCompassMask().eraseFaces(graphics,
					variant == 3 ? new Rectangle(50, 50, 10, 10) : new Rectangle(0, 0, 40, 40),
					x, new int[]{2, 2, 36}, 1, new int[]{0}, new int[]{variant == 4 ? 1 : 2},
					new int[]{variant >= 4 ? 2 : 1},
					variant == 1 ? new int[]{-2} : null, variant == 0 ? new byte[]{(byte) 255} : null);
				assertEquals(128, image.getRGB(4, 8) >>> 24);
			}
			finally
			{
				graphics.dispose();
			}
		}
	}

	@Test
	public void translatedBufferUsesCanvasCoordinatesAndClearsSharedEdges()
	{
		BufferedImage image = filledImage();
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.translate(-100, -200);
			new ActorCompassMask().eraseFaces(graphics, new Rectangle(100, 200, 40, 40),
				new int[]{104, 136, 136, 104}, new int[]{204, 204, 236, 236},
				2, new int[]{0, 0}, new int[]{2, 3}, new int[]{1, 2}, null, null);
			for (int y = 5; y < 35; y++)
			{
				for (int x = 5; x < 35; x++)
				{
					assertEquals(0, image.getRGB(x, y) >>> 24);
				}
			}
			assertEquals(128, image.getRGB(1, 1) >>> 24);
		}
		finally
		{
			graphics.dispose();
		}
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Rectangle;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

public class ActorMaskSelectorTest
{
	@Test
	public void localPlayerIsExcludedBeforeBoundsWorkAndDoesNotConsumeBudget()
	{
		ActorMaskSelector<Object> selector = new ActorMaskSelector<>();
		Object local = new Object(), other = new Object();
		selector.spawn(0, 0, local);
		selector.spawn(0, 1, other);
		List<Object> selected = new ArrayList<>();
		assertEquals(1, selector.select(false, 1, new Rectangle(0, 0, 100, 100), local, actor ->
		{
			assertNotSame(local, actor);
			return new Rectangle(10, 10, 20, 20);
		}));
		assertTrue(selected.isEmpty());
		selector.maskSelected(selected::add);
		assertEquals(Arrays.asList(other), selected);
		selector.maskSelected(actor -> fail("Selection must be consumed only once"));
	}

	@Test
	public void playerAndNpcBudgetsAndSwitchesAreIndependent()
	{
		ActorMaskSelector<Integer> players = new ActorMaskSelector<>();
		ActorMaskSelector<Integer> npcs = new ActorMaskSelector<>();
		for (int i = 0; i < 20; i++)
		{
			players.spawn(0, i, i);
			npcs.spawn(0, i, i);
		}
		Rectangle bounds = new Rectangle(0, 0, 100, 100);
		AtomicInteger playerMasks = new AtomicInteger(), npcMasks = new AtomicInteger();
		assertEquals(12, players.select(false, 12, bounds, null, actor -> null));
		assertEquals(12, npcs.select(false, 12, bounds, null, actor -> null));
		players.maskSelected(actor -> playerMasks.incrementAndGet());
		npcs.maskSelected(actor -> npcMasks.incrementAndGet());
		assertEquals(12, playerMasks.get());
		assertEquals(12, npcMasks.get());
		assertEquals(0, players.select(true, 12, bounds, null,
			actor -> { fail("Disabled player masking must skip bounds"); return null; }));
		players.maskSelected(actor -> fail("Disabled player masking must skip models"));
		assertEquals(1, npcs.select(false, 1, bounds, null, actor -> null));
		npcs.maskSelected(actor -> npcMasks.incrementAndGet());
		assertEquals(13, npcMasks.get());
		assertEquals(0, players.select(false, 0, bounds, null,
			actor -> { fail("Zero player budget must skip bounds"); return null; }));
		players.maskSelected(actor -> fail("Zero player budget must skip models"));
	}

	@Test
	public void largestOverlapsWinAndOffscreenActorsNeverRequestModels()
	{
		ActorMaskSelector<Integer> selector = new ActorMaskSelector<>();
		for (int i = 1; i <= 100; i++)
		{
			selector.spawn(0, i, i);
		}
		List<Integer> selected = new ArrayList<>();
		Rectangle bounds = new Rectangle(0, 0, 100, 100);
		Rectangle2D.Double scratch = new Rectangle2D.Double();
		int count = selector.select(false, 2, bounds, null, actor ->
		{
			scratch.setRect(actor > 3 ? 200 : 0, 0, actor * 10, actor * 10);
			return scratch;
		});
		selector.maskSelected(selected::add);
		assertEquals(2, count);
		assertEquals(Arrays.asList(3, 2), selected);

		// Unknown bounds remain candidates; equal overlaps use world and actor index order.
		selector.spawn(-1, 3, 103);
		selector.spawn(-1, 2, 102);
		selected.clear();
		assertEquals(3, selector.select(false, 3, bounds, null, actor -> null));
		selector.maskSelected(selected::add);
		assertEquals(Arrays.asList(102, 103, 1), selected);

		selector.select(false, 2, bounds, null, actor -> null);
		assertEquals(0, selector.select(false, 2, bounds, null, actor -> new Rectangle(200, 200, 20, 20)));
		selector.maskSelected(actor -> fail("No overlaps must allow rendering without a mask"));
	}

	@Test
	public void registryHandlesDespawnIndexReuseWorldUnloadAndShutdown()
	{
		ActorMaskSelector<Object> selector = new ActorMaskSelector<>();
		Object oldActor = new Object(), replacement = new Object();
		selector.spawn(1, 3, oldActor);
		selector.spawn(1, 3, replacement);
		selector.despawn(1, 3, oldActor);
		assertEquals(1, selector.size());
		selector.spawn(2, 3, new Object());
		selector.removeWorld(1);
		assertEquals(1, selector.size());
		selector.spawn(1, 3, replacement);
		selector.despawn(1, 3, replacement);
		assertEquals(1, selector.size());
		selector.clear();
		assertEquals(0, selector.size());
		assertEquals(0, selector.select(false, 12, new Rectangle(0, 0, 100, 100), null,
			actor -> { fail("Cleared actors must not be retained"); return null; }));
		selector.maskSelected(actor -> fail("Cleared actors must not be masked"));
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Color;
import java.util.EnumSet;
import org.junit.Test;
import static org.junit.Assert.*;

public class CompassDirectionTest
{
	private final NeverEatSoggyWeetbixConfig config = new NeverEatSoggyWeetbixConfig() {};

	@Test
	public void cameraColorsMoveWhileGeographicLabelsStayFixed()
	{
		assertEquals(config.currentColor(), CompassDirection.N.color(config, 0));
		assertEquals(config.oppositeColor(), CompassDirection.S.color(config, 0));
		assertEquals(config.currentSubColor(), CompassDirection.NE.color(config, 0));
		assertEquals(config.oppositeSubColor(), CompassDirection.SW.color(config, 0));
		assertEquals(config.currentColor(), CompassDirection.E.color(config, Math.PI / 2));
		assertEquals(config.oppositeColor(), CompassDirection.W.color(config, Math.PI / 2));
		assertEquals(config.currentSubColor(), CompassDirection.SE.color(config, Math.PI / 2));
		assertEquals(0, CompassDirection.N.x, 1e-9);
		assertEquals(1, CompassDirection.N.y, 1e-9);
	}

	@Test
	public void adjacentRolesAreIndependentInBothGroups()
	{
		NeverEatSoggyWeetbixConfig distinct = new NeverEatSoggyWeetbixConfig()
		{
			@Override public Color leftColor() { return Color.BLUE; }
			@Override public Color rightColor() { return Color.YELLOW; }
			@Override public Color leftSubColor() { return Color.CYAN; }
			@Override public Color rightSubColor() { return Color.MAGENTA; }
		};
		assertEquals(Color.BLUE, CompassDirection.W.color(distinct, 0));
		assertEquals(Color.YELLOW, CompassDirection.E.color(distinct, 0));
		assertEquals(Color.CYAN, CompassDirection.NW.color(distinct, 0));
		assertEquals(Color.MAGENTA, CompassDirection.SE.color(distinct, 0));
	}

	@Test
	public void exactTiesChooseClockwiseAndHeadingWraps()
	{
		assertEquals(CompassDirection.N.ordinal(), CompassDirection.current(Math.PI / 4 - 1e-6, false));
		assertEquals(CompassDirection.E.ordinal(), CompassDirection.current(Math.PI / 4, false));
		assertEquals(CompassDirection.NE.ordinal(), CompassDirection.current(0, true));
		assertEquals(CompassDirection.NW.ordinal(), CompassDirection.current(-1e-6, true));
		assertEquals(CompassDirection.NE.ordinal(), CompassDirection.current(Math.PI * 2, true));
		assertEquals(CompassDirection.N.ordinal(), CompassDirection.current(-Math.PI / 4, false));
	}

	@Test
	public void opacityMultipliesRatherThanReplacesColorAlpha()
	{
		Color half = CompassDirection.withOpacity(new Color(100, 120, 140, 128), 50);
		assertEquals(new Color(100, 120, 140, 64), half);
		assertEquals(128, CompassDirection.withOpacity(Color.WHITE, 50).getAlpha());
		assertEquals(191, CompassDirection.withOpacity(config.currentSubColor(), 75).getAlpha());
		assertEquals(0, CompassDirection.withOpacity(Color.RED, -1).getAlpha());
		assertEquals(255, CompassDirection.withOpacity(Color.RED, 101).getAlpha());
	}

	@Test
	public void letterAndConnectorSwitchesAreIndependent()
	{
		NeverEatSoggyWeetbixConfig cardinalOnly = new NeverEatSoggyWeetbixConfig()
		{
			@Override public boolean hideCardinals() { return true; }
			@Override public boolean showCardinalConnectors() { return true; }
			@Override public boolean showDiagonalConnectors() { return false; }
		};
		assertFalse(CompassDirection.N.lettersVisible(cardinalOnly));
		assertTrue(CompassDirection.N.connectorVisible(cardinalOnly, 0));
		assertTrue(CompassDirection.NE.lettersVisible(cardinalOnly));
		assertFalse(CompassDirection.NE.connectorVisible(cardinalOnly, 0));
		NeverEatSoggyWeetbixConfig diagonalOnly = new NeverEatSoggyWeetbixConfig()
		{
			@Override public boolean hideDiagonals() { return true; }
			@Override public boolean showDiagonalConnectors() { return true; }
			@Override public boolean showCardinalConnectors() { return false; }
		};
		assertTrue(CompassDirection.N.lettersVisible(diagonalOnly));
		assertFalse(CompassDirection.N.connectorVisible(diagonalOnly, 0));
		assertFalse(CompassDirection.NE.lettersVisible(diagonalOnly));
		assertTrue(CompassDirection.NE.connectorVisible(diagonalOnly, 0));
		for (CompassDirection direction : CompassDirection.ALL)
		{
			assertEquals(direction == CompassDirection.N || direction == CompassDirection.NE,
				direction.connectorVisible(config, 0));
			assertTrue(direction.lettersVisible(config));
		}
		for (int turn = 0; turn < 2; turn++)
		{
			EnumSet<CompassDirection> current = turn == 0 ? EnumSet.of(CompassDirection.N, CompassDirection.NE)
				: EnumSet.of(CompassDirection.E, CompassDirection.SE);
			EnumSet<CompassDirection> opposite = turn == 0 ? EnumSet.of(CompassDirection.S, CompassDirection.SW)
				: EnumSet.of(CompassDirection.W, CompassDirection.NW);
			for (int mask = 0; mask < 16; mask++)
			{
				final int switches = mask;
				NeverEatSoggyWeetbixConfig filtered = new NeverEatSoggyWeetbixConfig()
				{
					@Override public boolean onlyCurrentDirectionConnectors() { return (switches & 1) != 0; }
					@Override public boolean onlyOppositeDirectionConnectors() { return (switches & 2) != 0; }
					@Override public boolean showCardinalConnectors() { return (switches & 4) != 0; }
					@Override public boolean showDiagonalConnectors() { return (switches & 8) != 0; }
				};
				for (CompassDirection direction : CompassDirection.ALL)
				{
					boolean groupEnabled = direction.diagonal() ? (mask & 8) != 0 : (mask & 4) != 0;
					boolean selected = (mask & 3) == 0 || ((mask & 1) != 0 && current.contains(direction))
						|| ((mask & 2) != 0 && opposite.contains(direction));
					assertEquals("Switches " + mask + ", turn " + turn + ", direction " + direction,
						groupEnabled && selected, direction.connectorVisible(filtered, turn * Math.PI / 2));
				}
			}
		}
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Font;
import net.runelite.client.config.FontType;
import org.junit.Test;
import static org.junit.Assert.*;

public class CompassFontsTest
{
	@Test
	public void customFontsPreserveTheirIndependentSizesAndStyles()
	{
		Font selectedCardinal = new Font(Font.SERIF, Font.BOLD | Font.ITALIC, 25).deriveFont(25.5f);
		Font selectedSubDirection = new Font(Font.MONOSPACED, Font.PLAIN, 17).deriveFont(17.25f);
		NeverEatSoggyWeetbixConfig config = new NeverEatSoggyWeetbixConfig()
		{
			@Override public boolean useCustomFont() { return true; }
			@Override public FontType customFont() { return new FontType().withFont(selectedCardinal); }
			@Override public FontType subDirectionFont() { return new FontType().withFont(selectedSubDirection); }
		};
		CompassFonts fonts = CompassFonts.fromConfig(config);
		assertEquals(25.5f, fonts.cardinal.getSize2D(), 0f);
		assertEquals(17.25f, fonts.diagonal.getSize2D(), 0f);
		assertEquals(selectedCardinal.getFamily(), fonts.cardinal.getFamily());
		assertEquals(selectedSubDirection.getFamily(), fonts.diagonal.getFamily());
		assertEquals(selectedCardinal.getStyle(), fonts.cardinal.getStyle());
		assertEquals(selectedSubDirection.getStyle(), fonts.diagonal.getStyle());
		assertEquals(25.5f, selectedCardinal.getSize2D(), 0f);
