package com.nevereatsoggyweetbix;

import java.awt.geom.AffineTransform;
import java.awt.geom.PathIterator;
import java.awt.geom.Point2D;
import org.junit.Test;
import static org.junit.Assert.*;

public class CompassGeometryTest
{
	private static CompassAnchor anchor(double cameraY, double cameraZ, double pitch, double height)
	{
		return new CompassAnchor(new CompassProjection(
			CompassProjection.cameraMatrix(0, pitch, 6400, cameraY, cameraZ), 400, 300, 800),
			6400, 6400, height, 0, 0);
	}

	@Test
	public void labelsOccupyAllEightDirectionsAndSpokesLeaveTheCenterClear()
	{
		CompassAnchor anchor = anchor(5000, -1200, 0.7, 0);
		CompassGeometry geometry = new CompassGeometry();
		geometry.update(anchor, 256, 40);
		Point2D.Double center = anchor.project(0, 0);
		assertTrue(geometry.prepareLabelRing());
		assertTrue(geometry.labels[CompassDirection.N.ordinal()].y < center.y);
		assertTrue(geometry.labels[CompassDirection.S.ordinal()].y > center.y);
		assertTrue(geometry.labels[CompassDirection.E.ordinal()].x > center.x);
		assertTrue(geometry.labels[CompassDirection.W.ordinal()].x < center.x);
		for (CompassDirection direction : CompassDirection.ALL)
		{
			double labelRadius = 256 + 20 / anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
			Point2D.Double label = unproject(anchor, geometry.labels[direction.ordinal()]);
			assertEquals(anchor.x + direction.x * labelRadius, label.x, 1e-6);
			assertEquals(anchor.y + direction.y * labelRadius, label.y, 1e-6);
			for (double offset : new double[]{-60, 0, 60})
			{
				AffineTransform placement = new AffineTransform();
				assertTrue(geometry.labelTransform(direction, offset, placement));
				Point2D.Double character = unproject(anchor,
					new Point2D.Double(placement.getTranslateX(), placement.getTranslateY()));
				assertEquals("Character centers must follow the ring", labelRadius,
					character.distance(anchor.x, anchor.y), 0.1);
				double angle = Math.atan2(character.x - anchor.x, character.y - anchor.y);
				Point2D.Double before = anchor.project(Math.sin(angle - 1e-4) * labelRadius, Math.cos(angle - 1e-4) * labelRadius);
				Point2D.Double after = anchor.project(Math.sin(angle + 1e-4) * labelRadius, Math.cos(angle + 1e-4) * labelRadius);
				double length = before.distance(after);
				assertEquals("Character baselines must follow the tangent", (after.x - before.x) / length, placement.getScaleX(), 0.005);
				assertEquals((after.y - before.y) / length, placement.getShearY(), 0.005);
			}
			PathIterator iterator = geometry.spokes[direction.ordinal()].getPathIterator(null);
			double[] coordinates = new double[6];
			assertEquals(PathIterator.SEG_MOVETO, iterator.currentSegment(coordinates));
			Point2D.Double expectedStart = anchor.project(direction.x * 256 * 0.35, direction.y * 256 * 0.35);
			assertEquals(expectedStart.x, coordinates[0], 1e-6);
			assertEquals(expectedStart.y, coordinates[1], 1e-6);
			iterator.next();
			assertEquals(PathIterator.SEG_LINETO, iterator.currentSegment(coordinates));
			Point2D.Double expectedEnd = anchor.project(direction.x * 256 * 0.85, direction.y * 256 * 0.85);
			assertEquals(expectedEnd.x, coordinates[0], 1e-6);
			assertEquals(expectedEnd.y, coordinates[1], 1e-6);
			iterator.next();
			assertTrue(iterator.isDone());
		}
	}

	@Test
	public void ringsAndLabelsRemainWorldSpaceCirclesAcrossPitchYawAndZoom()
	{
		for (double pitch : new double[]{0.05, 0.3, 0.7, 1.3, Math.PI / 2})
		{
			for (double yaw : new double[]{0, 0.63, Math.PI / 2, Math.PI})
			{
				for (double scale : new double[]{400, 800, 1600})
				{
					CompassAnchor anchor = new CompassAnchor(new CompassProjection(
						CompassProjection.cameraMatrix(yaw, pitch,
							6400 + Math.sin(yaw) * 1400, 6400 - Math.cos(yaw) * 1400, -1200),
						400, 300, scale), 6400, 6400, 0, 0, 0);
					assertWorldRings(anchor, 256, 40);
				}
			}
		}
	}

	private static void assertWorldRings(CompassAnchor anchor, double radius, double bandPixels)
	{
		CompassGeometry geometry = new CompassGeometry();
		geometry.update(anchor, radius, bandPixels);
		double worldGap = bandPixels / anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
		PathIterator inner = geometry.inner.getPathIterator(null);
		PathIterator outer = geometry.outer.getPathIterator(null);
		double[] a = new double[6], b = new double[6];
		int points = 0;
		while (!inner.isDone())
		{
			assertFalse(outer.isDone());
			assertEquals(inner.currentSegment(a), outer.currentSegment(b));
			Point2D.Double groundInner = unproject(anchor, new Point2D.Double(a[0], a[1]));
			Point2D.Double groundOuter = unproject(anchor, new Point2D.Double(b[0], b[1]));
			assertEquals(radius, groundInner.distance(anchor.x, anchor.y), 1e-6);
			assertEquals(radius + worldGap, groundOuter.distance(anchor.x, anchor.y), 1e-6);
			inner.next();
			outer.next();
			points++;
		}
		assertEquals(CompassGeometry.SAMPLES + 1, points);
		assertTrue(outer.isDone());
		for (CompassDirection direction : CompassDirection.ALL)
		{
			Point2D.Double ground = unproject(anchor, geometry.labels[direction.ordinal()]);
			assertEquals(anchor.x + direction.x * (radius + worldGap / 2), ground.x, 1e-6);
			assertEquals(anchor.y + direction.y * (radius + worldGap / 2), ground.y, 1e-6);
		}
	}

	private static Point2D.Double unproject(CompassAnchor anchor, Point2D.Double point)
	{
		assertNotNull(point);
		Point2D.Double ground = anchor.projection.unproject(point.x - anchor.translateX,
			point.y - anchor.translateY, anchor.height);
		assertNotNull(ground);
		return ground;
	}

	@Test
	public void behindCameraRingSectionsStartNewPathsInsteadOfBridging()
	{
		CompassGeometry geometry = new CompassGeometry();
		CompassAnchor anchor = anchor(6300, -100, 0.2, 0);
		geometry.update(anchor, 256, 40);
		int moves = 0;
		PathIterator path = geometry.inner.getPathIterator(null);
		double[] coordinates = new double[6];
		while (!path.isDone())
		{
			int type = path.currentSegment(coordinates);
			assertTrue(Double.isFinite(coordinates[0]));
			assertTrue(Double.isFinite(coordinates[1]));
			assertNotEquals(PathIterator.SEG_CLOSE, type);
			if (type == PathIterator.SEG_MOVETO)
			{
				moves++;
			}
			path.next();
		}
		assertEquals(2, moves);
		assertNull(geometry.labels[CompassDirection.S.ordinal()]);
		assertNull(geometry.spokes[CompassDirection.S.ordinal()].getCurrentPoint());
	}

	@Test
	public void zeroRadiusCollapsesInnerRingAndSpokesButRetainsOuterBandAndLabels()
	{
		CompassAnchor anchor = anchor(5000, -1200, 0.7, 0);
		CompassGeometry geometry = new CompassGeometry();
		geometry.update(anchor, 0, 40);
		assertNull(geometry.inner.getCurrentPoint());
		assertNotNull(geometry.outer.getCurrentPoint());
		double radius = 20 / anchor.projection.horizontalScaleAt(anchor.x, anchor.y, anchor.height);
		for (CompassDirection direction : CompassDirection.ALL)
		{
			assertNull(geometry.spokes[direction.ordinal()].getCurrentPoint());
			Point2D.Double point = unproject(anchor, geometry.labels[direction.ordinal()]);
			assertEquals(radius, point.distance(anchor.x, anchor.y), 1e-6);
		}
	}

	@Test
	public void missingModelAndInvalidProjectionHaveSafeFallbacks()
	{
		assertEquals(180, CompassAnchor.modelTop(null, 180), 0);
		assertEquals(0, CompassAnchor.modelTop(null, -1), 0);
		CompassGeometry geometry = new CompassGeometry();
		geometry.update(anchor(5000, -1200, 0.7, 0), 256, 40);
		assertNotNull(geometry.inner.getCurrentPoint());
		geometry.update(anchor(9000, 0, 0, 0), 256, 40);
		assertNull(geometry.inner.getCurrentPoint());
		assertNull(geometry.outer.getCurrentPoint());
		for (CompassDirection direction : CompassDirection.ALL)
		{
			assertNull(geometry.labels[direction.ordinal()]);
			assertNull(geometry.spokes[direction.ordinal()].getCurrentPoint());
		}
	}
}

package com.nevereatsoggyweetbix;

import java.awt.geom.Point2D;
import org.junit.Test;
import static org.junit.Assert.*;

public class CompassProjectionTest
{
	@Test
	public void groundProjectionRoundTripsAcrossCameraAnglesAndHeights()
	{
		for (double yaw : new double[]{0, 0.63, Math.PI / 2, Math.PI, -1.71, Math.PI * 2})
		{
			for (double pitch : new double[]{0.25, 0.8, 1.4})
			{
				CompassProjection projection = new CompassProjection(
					CompassProjection.cameraMatrix(yaw, pitch,
						6400 + Math.sin(yaw) * 1500, 6400 - Math.cos(yaw) * 1500, -1200),
					517, 363, 800);
				for (double height : new double[]{-512, 0, 512})
				{
					for (int offset = -128; offset <= 128; offset += 64)
					{
						double x = 6400 + offset, y = 6400 - offset;
						Point2D.Double screen = projection.project(x, y, height);
						assertNotNull(screen);
						Point2D.Double ground = projection.unproject(screen.x, screen.y, height);
						assertNotNull(ground);
						assertEquals(x, ground.x, 1e-6);
						assertEquals(y, ground.y, 1e-6);
					}
				}
			}
		}
	}

	@Test
	public void nearPlaneHorizonAndNonFiniteInputsAreRejected()
	{
		CompassProjection projection = new CompassProjection(
			CompassProjection.cameraMatrix(0, 0, 0, 0, 0), 400, 300, 800);
		assertNull(projection.project(0, 49, 0));
		assertNotNull(projection.project(0, 50, 0));
		assertNull(projection.project(0, -1000, 0));
		assertNull(projection.unproject(400, 300, 0));
		assertNull(projection.project(Double.NaN, 100, 0));
		assertNull(projection.unproject(Double.POSITIVE_INFINITY, 300, 0));
		assertNull(new CompassProjection(new double[3][4], 0, 0, 0).unproject(0, 0, 0));
	}
}

package com.nevereatsoggyweetbix;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class CompassTextLayerTest
{
	private static BufferedImage render(Shape glyph, Color color, int offset, boolean aa)
	{
		BufferedImage image = new BufferedImage(180, 180, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setClip(0, 0, 180, 180);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				aa ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF);
			new CompassTextLayer().draw(graphics, new Shape[]{glyph}, new Color[]{color}, new Color(0, 0, 0, 160), offset);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	@Test
	public void translucentForegroundReplacesShadowInsteadOfDarkeningOrIncreasingAlpha()
	{
		Color color = new Color(40, 180, 240, 96);
		BufferedImage image = render(new Rectangle(10, 10, 20, 20), color, 1, false);
		Color foreground = new Color(image.getRGB(15, 15), true);
		assertEquals(96, foreground.getAlpha());
		assertEquals(color.getRed(), foreground.getRed(), 2);
		assertEquals(color.getGreen(), foreground.getGreen(), 2);
		assertEquals(color.getBlue(), foreground.getBlue(), 2);
		assertEquals(160, image.getRGB(30, 20) >>> 24);
	}

	@Test
	public void maximumOffsetAndRotatedGlyphStayInScreenCoordinates()
	{
		Shape glyph = AffineTransform.getRotateInstance(Math.PI / 4, 20, 20)
			.createTransformedShape(new Rectangle(15, 15, 10, 10));
		BufferedImage image = render(glyph, Color.WHITE, 128, false);
		assertEquals(Color.WHITE.getRGB(), image.getRGB(20, 20));
		assertEquals(160, image.getRGB(148, 148) >>> 24);
		assertEquals(0, image.getRGB(148, 20) >>> 24);
		Rectangle bounds = CompassTextLayer.bounds(new Shape[]{glyph}, 128, new Rectangle(0, 0, 100, 100));
		assertTrue(bounds.getMaxX() <= 100);
		assertTrue(bounds.getMaxY() <= 100);
	}

	@Test
	public void finishedLayerPreservesTheSceneAndCanBeReusedWithoutStalePixels()
	{
		BufferedImage image = new BufferedImage(80, 80, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setClip(0, 0, 80, 80);
		graphics.setColor(Color.WHITE);
		graphics.fillRect(0, 0, 80, 80);
		CompassTextLayer layer = new CompassTextLayer();
		layer.draw(graphics, new Shape[]{new Rectangle(10, 10, 40, 40)}, new Color[]{new Color(255, 0, 0, 128)}, Color.BLACK, 1);
		assertEquals(255, image.getRGB(20, 20) >>> 24);
		assertEquals(Color.WHITE.getRGB(), image.getRGB(5, 5));
		graphics.setComposite(AlphaComposite.Clear);
		graphics.fillRect(0, 0, 80, 80);
		graphics.setComposite(AlphaComposite.SrcOver);
		layer.draw(graphics, new Shape[]{new Rectangle(10, 10, 10, 10)}, new Color[]{Color.WHITE}, Color.BLACK, 1);
		assertEquals(0, image.getRGB(40, 40) >>> 24);
		assertEquals(Color.WHITE.getRGB(), image.getRGB(15, 15));
		layer.clear();
		graphics.dispose();
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class ConnectorShadowTest
{
	private static class ConnectorConfig implements NeverEatSoggyWeetbixConfig
	{
		boolean shadow = true;
		boolean cardinals = true;
		boolean diagonals = false;
		boolean onlyCurrent;
		boolean onlyOpposite;
		int offset = 16;
		@Override public boolean enableDropShadow() { return shadow; }
		@Override public int dropShadowOffset() { return offset; }
		@Override public Color dropShadowColor() { return new Color(0, 0, 0, 128); }
		@Override public boolean showCardinalConnectors() { return cardinals; }
		@Override public boolean showDiagonalConnectors() { return diagonals; }
		@Override public boolean onlyCurrentDirectionConnectors() { return onlyCurrent; }
		@Override public boolean onlyOppositeDirectionConnectors() { return onlyOpposite; }
		@Override public boolean connectorDirectionColors() { return false; }
		@Override public Color baseColor() { return new Color(255, 255, 255, 128); }
		@Override public int connectorThickness() { return 2; }
		@Override public int overallOpacity() { return 50; }
		@Override public boolean showInnerRing() { return false; }
		@Override public boolean showOuterRing() { return false; }
		@Override public boolean hideCardinals() { return true; }
		@Override public boolean hideDiagonals() { return true; }
		@Override public boolean directionalIndicatorEnabled() { return false; }
	}

	private static CompassGeometry geometry()
	{
		CompassGeometry geometry = new CompassGeometry();
		geometry.spokes[CompassDirection.N.ordinal()].moveTo(20, 20);
		geometry.spokes[CompassDirection.N.ordinal()].lineTo(50, 20);
		geometry.spokes[CompassDirection.NE.ordinal()].moveTo(20, 70);
		geometry.spokes[CompassDirection.NE.ordinal()].lineTo(50, 70);
		geometry.spokes[CompassDirection.S.ordinal()].moveTo(20, 120);
		geometry.spokes[CompassDirection.S.ordinal()].lineTo(50, 120);
		return geometry;
	}

	private static BufferedImage render(NeverEatSoggyWeetbixConfig config, CompassGeometry geometry)
	{
		BufferedImage image = new BufferedImage(240, 240, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			NeverEatSoggyWeetbixOverlay overlay = new NeverEatSoggyWeetbixOverlay(null, config);
			graphics.clip(overlay.drawingBounds(new Rectangle(0, 0, 240, 240), geometry, 0));
			overlay.drawCompass(graphics, 0, geometry);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	@Test
	public void shadowsRespectToggleVisibilityColorAndOpacity()
	{
		ConnectorConfig config = new ConnectorConfig();
		CompassGeometry geometry = geometry();
		BufferedImage image = render(config, geometry);
		assertEquals(new Color(255, 255, 255, 64).getRGB(), image.getRGB(30, 20));
		assertEquals(new Color(0, 0, 0, 64).getRGB(), image.getRGB(46, 36));
		assertEquals(0, image.getRGB(30, 70));
		assertEquals(0, image.getRGB(46, 86));
		config.shadow = false;
		image = render(config, geometry);
		assertEquals(64, image.getRGB(30, 20) >>> 24);
		assertEquals(0, image.getRGB(46, 36));
		config.shadow = true;
		config.cardinals = false;
		config.diagonals = true;
		image = render(config, geometry);
		assertEquals(0, image.getRGB(30, 20));
		assertEquals(0, image.getRGB(46, 36));
		assertEquals(64, image.getRGB(30, 70) >>> 24);
		assertEquals(64, image.getRGB(46, 86) >>> 24);
		config.cardinals = true;
		config.onlyCurrent = true;
		image = render(config, geometry);
		assertEquals(64, image.getRGB(30, 20) >>> 24);
		assertEquals(64, image.getRGB(30, 70) >>> 24);
		assertEquals(0, image.getRGB(30, 120));
		assertEquals(0, image.getRGB(46, 136));
		NeverEatSoggyWeetbixOverlay overlay = new NeverEatSoggyWeetbixOverlay(null, config);
		assertTrue(overlay.drawingBounds(new Rectangle(18, 115, 35, 5), geometry, 0).isEmpty());
		config.onlyCurrent = false;
		config.onlyOpposite = true;
		image = render(config, geometry);
		assertEquals(0, image.getRGB(30, 20));
		assertEquals(0, image.getRGB(46, 36));
		assertEquals(0, image.getRGB(30, 70));
		assertEquals(64, image.getRGB(30, 120) >>> 24);
		assertEquals(64, image.getRGB(46, 136) >>> 24);
		config.onlyCurrent = true;
		image = render(config, geometry);
		assertEquals(64, image.getRGB(30, 20) >>> 24);
		assertEquals(64, image.getRGB(30, 120) >>> 24);
	}
}

package com.nevereatsoggyweetbix;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class DirectionLabelRenderingTest
{
	private static final class LabelConfig implements NeverEatSoggyWeetbixConfig
	{
		DirectionLabelMode mode = DirectionLabelMode.ABBREVIATIONS;
		String definitions = "N=Never eat soggy WeetBix";
		boolean hidden;
		boolean shadow;
		int padding = 4;
		LetterRotation rotation;

		@Override public DirectionLabelMode labelMode() { return mode; }
		@Override public String customLabels() { return definitions; }
		@Override public boolean hideCardinals() { return hidden; }
		@Override public boolean hideDiagonals() { return true; }
		@Override public boolean showInnerRing() { return false; }
		@Override public boolean showOuterRing() { return false; }
		@Override public boolean showCardinalConnectors() { return false; }
		@Override public boolean showDiagonalConnectors() { return false; }
		@Override public boolean directionalIndicatorEnabled() { return false; }
		@Override public LetterRotation letterRotation() { return rotation; }
		@Override public boolean enableDropShadow() { return shadow; }
		@Override public int dropShadowOffset() { return 16; }
		@Override public int ringPadding() { return padding; }
	}

	@Test
	public void editedLabelsRefreshTheirRenderingAndBoundsWithRotationAndShadows()
	{
		for (LetterRotation rotation : LetterRotation.values())
		{
			for (boolean shadow : new boolean[]{false, true})
			{
				LabelConfig config = new LabelConfig();
				config.rotation = rotation;
				config.shadow = shadow;
				NeverEatSoggyWeetbixOverlay overlay = new NeverEatSoggyWeetbixOverlay(null, config);
				CompassGeometry geometry = new CompassGeometry();
				CompassAnchor anchor = new CompassAnchor(new CompassProjection(
					CompassProjection.cameraMatrix(0, 0.8, 0, -1400, -1200), 300, 300, 800),
					0, 0, 0, 0, 0);
				Rectangle abbreviation = render(overlay, geometry, anchor, true);
				config.mode = DirectionLabelMode.FULL_NAMES;
				Rectangle fullName = render(overlay, geometry, anchor, true);
				assertTrue(fullName.width > abbreviation.width);
				config.mode = DirectionLabelMode.CUSTOM;
				Rectangle custom = render(overlay, geometry, anchor, true);
				assertTrue(custom.width > fullName.width);
				config.definitions += "\nNE=" + "hidden".repeat(100);
				assertEquals("Hidden diagonals must not inflate ring spacing", custom, render(overlay, geometry, anchor, true));
				config.hidden = true;
				assertTrue(render(overlay, geometry, anchor, false).isEmpty());
				config.hidden = false;
				config.definitions = "N=";
				assertTrue(render(overlay, geometry, anchor, false).isEmpty());
				if (rotation == LetterRotation.ROTATION)
				{
					config.definitions = "N=W";
					render(overlay, geometry, anchor, true);
					double shortBand = overlay.labelBandWidth();
					config.definitions = "N=WWWWWWWWWWWW";
					render(overlay, geometry, anchor, true);
					assertEquals("Long curved words must not widen the band", shortBand, overlay.labelBandWidth(), 1e-9);
					config.padding = 8;
					render(overlay, geometry, anchor, true);
					assertEquals("Padding applies to both sides", shortBand + 8, overlay.labelBandWidth(), 1e-9);
				}
			}
		}
	}

	private static Rectangle render(NeverEatSoggyWeetbixOverlay overlay, CompassGeometry geometry, CompassAnchor anchor, boolean visible)
	{
		BufferedImage image = new BufferedImage(600, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			overlay.invalidateFonts();
			overlay.updateFonts(graphics);
			overlay.updateGeometry(geometry, anchor);
			for (CompassDirection direction : CompassDirection.ALL)
			{
				if (direction != CompassDirection.N)
				{
					geometry.labels[direction.ordinal()] = null;
				}
			}
			overlay.prepareLabels(geometry);
			Rectangle bounds = overlay.drawingBounds(new Rectangle(0, 0, 600, 600), geometry, 0);
			overlay.drawCompass(graphics, 0, geometry);
			int pixels = 0;
			for (int y = 0; y < image.getHeight(); y++)
			{
				for (int x = 0; x < image.getWidth(); x++)
				{
					if ((image.getRGB(x, y) >>> 24) != 0)
					{
						assertTrue("Text and shadows must fit the clipping bounds", bounds.contains(x, y));
						pixels++;
					}
				}
			}
			assertEquals(visible, pixels > 0);
			return bounds;
		}
		finally
		{
			graphics.dispose();
		}
	}
}

